using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Model.DataSetLibrarySystemTableAdapters; // needed to see the TabUserTableAdapter

namespace Model
{
    // DATA ACCESS LAYER for users.
    // It only reads and writes the TabUser table and returns raw data (a DataTable).
    // Turning that into User objects is the job of UserLogic.
    public class UserDAO
    {
        // The TableAdapter was generated by Visual Studio from the DataSet
        // (DataSetLibrarySystem.xsd) and is what runs the SQL.
        private TabUserTableAdapter tabUserTableAdapter = new TabUserTableAdapter();

        // ================= READ =================

        // Returns every user. The method name must match the query name I gave in the
        // DataSet designer.
        public DataSetLibrarySystem.TabUserDataTable BrowseUsers()
        {
            return tabUserTableAdapter.BrowserUsers();
        }

        // Returns the row that matches this username and password, or an empty table.
        //
        // This is the Assessment 1 feedback fix. The login used to call BrowseUsers()
        // and compare every user in C#. GetDataByCredentials does the comparison in a
        // WHERE clause, so only the matching row comes back. The values go in as
        // parameters (@username, @password), which also keeps the login safe from SQL
        // injection.
        public DataSetLibrarySystem.TabUserDataTable FindByCredentials(string username, string password)
        {
            return tabUserTableAdapter.GetDataByCredentials(username, password);
        }

        // ================= WRITE =================
        // These use the Insert, Update and Delete commands the DataSet generated for
        // TabUser. Each one returns how many rows were affected, so the logic layer can
        // tell whether the command changed anything.

        // No UID here because UID is an identity column, so SQL Server sets it.
        public int Insert(string userName, string password, int userLevel)
        {
            return tabUserTableAdapter.Insert(userName, password, userLevel);
        }

        // New values first, then the UID that goes in the WHERE clause to find the row.
        // The order is fixed by the generated command.
        public int Update(string userName, string password, int userLevel, int originalUid)
        {
            return tabUserTableAdapter.Update(userName, password, userLevel, originalUid);
        }

        // The UID is the primary key, so it is enough to identify the row.
        public int Delete(int originalUid)
        {
            return tabUserTableAdapter.Delete(originalUid);
        }
    }
}